class BBlivechat extends AJAXChat { function initCustomConfig() { global $db, $config, $bblc_settings, $bblc_rooms, $bblc_default_room, $bblc_default_name, $bblivechat; $bblivechat = $this; $this->setConfig('dbConnection', 'link', $db->get_db_connect_id()); $ac_map = [ 'chatClosed', 'layout', 'defaultChannelName', 'chatBotName', 'allowPrivateChannels', 'allowPrivateMessages', 'allowUserMessageDelete', 'inactiveTimeout', 'inactiveCheckInterval', 'defaultBanTime', 'requestMessagesLimit', 'maxUsersLoggedIn', 'messageTextMaxLength', 'maxMessageRate', 'refreshRate', 'displayAvatars', 'announce', 'showChannelMessages', ]; $ac_count = count($ac_map); if (!empty($bblc_settings) && count($bblc_settings) == $ac_count) { for ($i=0; $i<$ac_count; $i++) { $this->setConfig($ac_map[$i], '', $bblc_settings[$i]); } } $this->setConfig('defaultChannelName', '', $bblc_default_name); $this->setConfig('defaultChannelID', '', $bblc_default_room); $this->setConfig('sessionCookiePath', '', $config['cookie_path']); $this->setConfig('sessionCookieDomain', '', $config['cookie_domain']); $this->setConfig('sessionCookieSecure', '', (bool) $config['cookie_secure']); } function initCustomRequestVars() { if (!$this->getRequestVar('logout')) { $this->setRequestVar('login', true); } } function revalidateUserID() { global $user; return $this->getUserID() == $user->data['user_id']; } function getValidLoginUserData() { global $user; $groups = explode(',', $user->data['usergroups']); if ($user->data['user_type'] == USER_FOUNDER || in_array('ADMINISTRATORS', $groups)) { $role = AJAX_CHAT_ADMIN; } else if (in_array('GLOBAL_MODERATORS', $groups)) { $role = AJAX_CHAT_MODERATOR; } else { $role = AJAX_CHAT_USER; } return [ 'userID' => $user->data['user_id'], 'userName' => $this->trimUserName($user->data['username']), 'userRole' => $role, ]; } function &getAllChannels() { global $user, $bblc_rooms; if($this->_allChannels === null) { $this->_allChannels = []; if (count($bblc_rooms)) { $ugids = (array) json_decode("[{$user->data['ugids']}]", true); $ugnames = (array) json_decode("[{$user->data['usergroups']}]", true); foreach ($bblc_rooms as $id => $room) { if ($user->data['user_type'] == USER_FOUNDER || in_array('ADMINISTRATORS', $ugnames) || count(array_intersect($room['groups'], $ugids))) { $room_name = $this->trimString($room['name']); $this->_allChannels[$room_name] = $id; } } } } return $this->_allChannels; } }